args.sparql:
SELECT DISTINCT ?father ?fatherLabel ?gfLiteral ?grandfather ?grandfatherLabel WHERE {
  dbr:Archambaud_VIII_of_Bourbon dbp:father ?father .
  OPTIONAL { ?father rdfs:label ?fatherLabel }
  OPTIONAL { ?father dbp:father ?gfLiteral }
  OPTIONAL {
    ?grandfather rdfs:label ?grandfatherLabel .
    FILTER(STR(?grandfatherLabel)=STR(?gfLiteral))
  }
} LIMIT 20

